<script setup>
import { computed, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useFinanceSession } from './session'
import logo from '../assets/images/logo/shishli-logo.webp'
const session = useFinanceSession(), route = useRoute(), router = useRouter()
const menuOpen = ref(false), logoutBusy = ref(false)
const links = [ ['/', 'لوحة التحكم', 'reports.view', 'chart-column'], ['/revenues', 'الإيرادات اليومية', 'revenues.view', 'wallet'], ['/expenses', 'المصروفات', 'expenses.view', 'arrow-up-left'], ['/purchases', 'المشتريات', 'purchases.view', 'shopping-bag'], ['/suppliers', 'الموردون', 'suppliers.view', 'truck'], ['/reports', 'التقارير المالية', 'reports.view', 'chart-column'], ['/users', 'المستخدمون', 'users.manage', 'users'], ['/audit', 'سجل التدقيق', 'audit.view', 'history'], ['/settings', 'الإعدادات', 'settings.manage', 'settings'] ]
const visible = computed(() => links.filter(l => session.can(l[2])))
async function logout() { logoutBusy.value = true; try { await session.logout() } catch { /* Local session has been cleared. */ } finally { logoutBusy.value = false; router.replace('/login') } }
</script>
<template><RouterView v-if="route.meta.public" /><div v-else class="finance-shell" dir="rtl">
<button v-if="menuOpen" type="button" class="finance-sidebar-backdrop" aria-label="إغلاق القائمة الجانبية" @click="menuOpen = false" />
<a class="skip" href="#content">الانتقال إلى المحتوى</a><aside id="finance-sidebar" :class="{ open: menuOpen }" aria-label="قائمة الإدارة المالية"><div class="finance-sidebar-brand"><div class="brand"><img :src="logo" alt="Shishli Fresh"><div class="finance-brand-copy"><strong>Shishli <span>Finance</span></strong><small>الإدارة المالية الداخلية</small></div></div><button class="finance-sidebar-close" type="button" aria-label="إغلاق قائمة المالية" @click="menuOpen = false"><FinanceIcon name="x" /></button></div><nav aria-label="التنقل المالي"><div class="finance-nav-label">الإدارة المالية</div><RouterLink v-for="link in visible" :key="link[0]" :to="link[0]" @click="menuOpen = false"><FinanceIcon :name="link[3]" />{{ link[1] }}</RouterLink></nav><div class="sidebar-note"><span class="live-dot"></span> إدخال مالي يدوي<small>Shishli Fresh · مساحة عمل مستقلة</small></div></aside>
<div class="workspace"><header class="topbar"><button class="mobile-toggle" type="button" @click="menuOpen = !menuOpen" :aria-expanded="menuOpen" aria-controls="finance-sidebar" :aria-label="menuOpen ? 'إغلاق قائمة المالية' : 'فتح قائمة المالية'"><FinanceIcon name="menu" /></button><div class="finance-breadcrumb"><span>مطعم شيشلي</span><span class="finance-breadcrumb-separator" aria-hidden="true">/</span><h1>{{ route.meta.title }}</h1></div><div class="account"><span class="avatar" aria-hidden="true"><FinanceIcon name="user-round" /></span><div class="finance-account-label">{{ session.user?.name }}<small>الإدارة المالية</small></div><button type="button" :disabled="logoutBusy" @click="logout">{{ logoutBusy ? 'جارٍ الخروج…' : 'خروج' }}</button></div></header><main id="content"><RouterView :key="route.path" /></main><footer>Shishli Finance · {{ new Date().getFullYear() }}<span>البيانات المالية المدخلة يدويًا</span></footer></div></div></template>
